record.field:
action = False


def toast(title, message, kind='warning', sticky=False, next_action=False):
    params = {
        'title': title,
        'message': message,
        'type': kind,
        'sticky': sticky,
    }
    if next_action:
        params['next'] = next_action
    return {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': params}


def reload_evaluation(rec):
    view = env.ref('hr_employment_custom.view_employee_performance_evaluation_form', raise_if_not_found=False)
    action = {
        'type': 'ir.actions.act_window',
        'name': rec.x_name or 'Employee Performance Evaluation',
        'res_model': rec._name,
        'res_id': rec.id,
        'view_mode': 'form',
        'target': 'current',
    }
    if view:
        action['views'] = [(view.id, 'form')]
    return action


def score_grade_rating(total):
    if total >= 51:
        return 'excellent', '5'
    if total >= 41:
        return 'very_good', '4'
    if total >= 31:
        return 'good', '3'
    return 'acceptable', '2'


for rec in records.sudo():
    if rec.x_state in ('signature_requested', 'signed'):
        action = toast(
            'Generate PDF',
            'This performance evaluation has already entered the signature lifecycle. PDF regeneration is blocked.',
            'warning',
            True,
            reload_evaluation(rec),
        )
        continue

    employee = rec.x_employee_id.sudo() if rec.x_employee_id else False

    if not employee:
        action = toast('Generate PDF', 'Cannot generate the performance evaluation form without a linked employee.', 'danger', True, reload_evaluation(rec))
        continue

    if not rec.x_period_date_from or not rec.x_period_date_to:
        action = toast('Generate PDF', 'Set both Evaluation Period From and Evaluation Period To before generating the form.', 'warning', True, reload_evaluation(rec))
        continue

    if rec.x_period_date_to < rec.x_period_date_from:
        action = toast('Generate PDF', 'Evaluation Period To cannot be earlier than Evaluation Period From.', 'warning', True, reload_evaluation(rec))
        continue

    lines = rec.x_line_ids.sorted(key=lambda line: line.x_sequence or 0)
    if len(lines) != 12:
        action = toast('Generate PDF', 'The evaluation must contain exactly 12 evaluation items before generating the form.', 'warning', True, reload_evaluation(rec))
        continue

    invalid_lines = []
    unscored_lines = []
    total = 0

    for line in lines:
        score = line.x_score or 0
        if score < 1 or score > 5:
            if score == 0:
                unscored_lines.append(str(line.x_sequence or line.id))
            else:
                invalid_lines.append(str(line.x_sequence or line.id))
        else:
            total += score

    if invalid_lines:
        action = toast('Generate PDF', 'Scores must be between 1 and 5. Invalid item(s): %s.' % ', '.join(invalid_lines), 'warning', True, reload_evaluation(rec))
        continue

    if unscored_lines:
        action = toast('Generate PDF', 'All 12 evaluation items must be scored from 1 to 5 before generating the form. Unscored item(s): %s.' % ', '.join(unscored_lines), 'warning', True, reload_evaluation(rec))
        continue

    generated_on = datetime.datetime.now()
    form_code = rec.x_reference_code or 'MCEP-HR-F-0018'
    form_title = 'Performance Evaluation'
    emp_part = employee.id if employee else 0

    document_reference = rec.x_document_reference
    if not document_reference:
        document_reference = '%s-%05d-%05d' % (form_code, emp_part, rec.id)
    elif '-EMP-' in document_reference:
        document_reference = document_reference.replace('-EMP-', '-', 1)

    grade, rating = score_grade_rating(total)
    percentage = round((float(total) / 60.0) * 100.0, 2)

    vals = {
        'x_state': rec.x_state or 'draft',
        'x_reference_code': form_code,
        'x_document_reference': document_reference,
        'x_total_score': total,
        'x_max_score': 60,
        'x_score_percentage': percentage,
        'x_grade': grade,
        'x_star_rating': rating,
        'x_responsible_user_id': rec.x_responsible_user_id.id or env.user.id,
    }

    if employee.parent_id and employee.parent_id.user_id:
        vals['x_direct_manager_user_id'] = employee.parent_id.user_id.id

    if 'hr_responsible_id' in employee._fields and employee.hr_responsible_id:
        vals['x_hr_user_id'] = employee.hr_responsible_id.id

    normalized_name = '%s - %s - %s' % (
        employee.name or employee.display_name or 'Employee',
        form_title,
        document_reference,
    )
    vals['x_name'] = normalized_name

    rec.write(vals)
    rec = rec.sudo().browse(rec.id)

    report_xmlid = 'hr_employment_custom.action_report_mcep_employee_performance_evaluation'
    pdf_content, _content_type = env['ir.actions.report'].sudo()._render_qweb_pdf(report_xmlid, [rec.id])

    filename = '%s - %s.pdf' % (rec.x_document_reference or form_code, form_title)

    attachment = env['ir.attachment'].sudo().create({
        'name': filename,
        'type': 'binary',
        'raw': pdf_content,
        'mimetype': 'application/pdf',
        'res_model': rec._name,
        'res_id': rec.id,
    })

    rec.write({
        'x_pdf_attachment_id': attachment.id,
        'x_generated_on': generated_on,
        'x_state': 'generated',
    })

    employee.message_post(
        body='تم توليد نموذج تقييم الأداء %s وربطه بسجل الموظف.' % form_code,
        subtype_xmlid='mail.mt_note',
        attachment_ids=[attachment.id],
    )

    action = toast('Generate PDF', '%s was generated and posted to the employee record.' % form_title, 'success', False, reload_evaluation(rec))
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

action = False
for rec in records.sudo():
    attachment = rec.x_pdf_attachment_id
    if attachment:
        action = {
            'type': 'ir.actions.act_url',
            'url': '/web/content/%s?download=true' % attachment.id,
            'target': 'self',
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Download Generated PDF',
                'message': 'No generated PDF is linked to this performance evaluation yet.',
                'type': 'warning',
                'sticky': False,
            }
        }
    break
if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

